<script setup>
import { ref, reactive, onMounted } from 'vue'
const props = defineProps({ api: { type: Function, required: true } })
const ghl = ref(null), ghlUrl = ref('')
const google = ref(null), candidates = ref([]), managerId = ref(''), customerId = ref(''), loginId = ref(''), connectUrl = ref('')
const grants = ref([]), code = ref(''), pending = ref(null), error = ref(''), notice = ref(''), busy = ref(false)
const strategy = reactive({ services: '', audience: '', goals: '', constraints: '', conversionDefinition: '', segmentFieldIds: [] })
const segmentFields = ref(''), mappingText = reactive({})
async function refresh() {
  try {
    const [connection, context, access, crm] = await Promise.all([props.api('/api/google'), props.api('/api/reporting/context'), props.api('/api/mcp/grants'), props.api('/api/ghl')])
    ghl.value = crm; google.value = connection; Object.assign(strategy, context); segmentFields.value = context.segmentFieldIds.join(', '); grants.value = access.grants
    for (const account of connection.accounts) mappingText[account.customer_id] = Object.entries(account.campaign_mappings).map(([utm, id]) => `${utm}=${id}`).join('\n')
  } catch (cause) { error.value = cause.message }
}
async function act(fn, message = '') { busy.value = true; error.value = ''; notice.value = ''; try { await fn(); notice.value = message } catch (cause) { error.value = cause.message } finally { busy.value = false } }
function connect() { return act(async () => { connectUrl.value = (await props.api('/api/google/connect', { method: 'POST' })).url }) }
function discover() { return act(async () => { const data = await props.api(`/api/google/accounts${managerId.value ? `?managerId=${managerId.value.replace(/-/g, '')}` : ''}`); candidates.value = data.accounts; if (data.truncated) notice.value = 'The account list is partial. You can select an account directly by its ID.' }) }
function select(id = customerId.value, login = loginId.value) { return act(async () => { await props.api('/api/google/accounts', { method: 'POST', body: JSON.stringify({ customerId: String(id).replace(/-/g, ''), loginCustomerId: login ? String(login).replace(/-/g, '') : null }) }); await refresh() }, 'Account selected') }
function disconnect() { if (confirm('Disconnect Google Ads for this workspace? Saved reports will remain available.')) return act(async () => { await props.api('/api/google', { method: 'DELETE' }); candidates.value = []; connectUrl.value = ''; await refresh() }) }
function removeAccount(id) { return act(async () => { await props.api(`/api/google/accounts/${id}`, { method: 'DELETE' }); await refresh() }) }
function saveContext() { return act(async () => { await props.api('/api/reporting/context', { method: 'PUT', body: JSON.stringify({ ...strategy, segmentFieldIds: segmentFields.value.split(',').map(s => s.trim()).filter(Boolean) }) }) }, 'Marketing goals saved') }
function saveMappings(id) { return act(async () => {
  const mappings = Object.fromEntries(mappingText[id].split('\n').filter(line => line.trim()).map(line => { const split = line.lastIndexOf('='); if (split < 1) throw new Error('Use one UTM campaign=Google campaign ID pair per line'); return [line.slice(0, split).trim(), line.slice(split + 1).trim()] }))
  await props.api(`/api/google/accounts/${id}/mappings`, { method: 'PUT', body: JSON.stringify({ mappings }) })
}, 'Campaign mappings saved') }
function inspect() { return act(async () => { pending.value = await props.api(`/api/mcp/requests/${code.value.trim().toUpperCase()}`) }) }
function approve() { return act(async () => { await props.api('/api/mcp/approve', { method: 'POST', body: JSON.stringify({ code: code.value.trim().toUpperCase() }) }); code.value = ''; pending.value = null }, 'Approved. Return to your AI assistant to finish connecting.') }
function revoke(id) { return act(async () => { await props.api(`/api/mcp/grants/${id}`, { method: 'DELETE' }); await refresh() }, 'Access revoked') }
const mcpUrl = `${location.origin}/mcp`
onMounted(refresh)
</script>
<template>
  <div class="connections"><span class="eyebrow">YOUR CONNECTED WORKSPACE</span><h1>Connections & goals</h1><p>Connect your own accounts. Reports and AI access stay within this workspace.</p><div v-if="error" class="error" role="alert">{{ error }}</div><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <section class="panel"><h2>HighLevel CRM</h2><p>{{ ghl?.connected ? 'Connected to location ' + ghl.locationId : 'Connect your own HighLevel location to include business information, customer segments and sales outcomes. Website tracking also works without a CRM connection.' }}</p><p v-if="ghl && !ghl.configured">The HighLevel integration has not been configured for this installation yet.</p><button :disabled="busy || !ghl?.configured" @click="act(async () => { ghlUrl = (await api('/api/ghl/connect', { method: 'POST' })).url })">{{ ghl?.connected ? 'Reconnect HighLevel' : 'Connect HighLevel' }}</button> <a v-if="ghlUrl" :href="ghlUrl" target="_blank" rel="noopener noreferrer">Continue to HighLevel ↗</a><p v-if="ghl?.connected">Disconnecting HighLevel also revokes connected AI assistants. You can reconnect them afterwards.</p><button v-if="ghl?.connected" :disabled="busy" @click="act(async () => { await api('/api/ghl', { method: 'DELETE' }); await refresh() })">Disconnect HighLevel</button></section>
    <section class="panel"><div class="heading"><h2>Google Ads</h2><button :disabled="busy" @click="refresh">Refresh connections</button></div><p v-if="!google?.configured">Google OAuth must be configured by Xaylo before accounts can connect.</p><template v-else><p>{{ google.connected ? 'Connected. Only selected advertising accounts are available to your reports and AI tools.' : 'Connect Google, then select the advertising accounts you want Xaylo to analyse.' }}</p><button :disabled="busy" @click="connect">{{ google.connected ? 'Reconnect Google Ads' : 'Connect Google Ads' }}</button> <a v-if="connectUrl" :href="connectUrl" target="_blank" rel="noopener noreferrer">Continue to Google ↗</a> <button v-if="google.connected" :disabled="busy" @click="disconnect">Disconnect</button>
    <template v-if="google.connected"><h3>Select accounts</h3><div class="row"><label>Manager account ID (optional)<input v-model="managerId" placeholder="123-456-7890"></label><button :disabled="busy" @click="discover">Find accessible accounts</button></div><div v-for="candidate in candidates" :key="candidate.id" class="candidate"><span>{{ candidate.name }} · {{ candidate.id }}</span><button v-if="candidate.manager !== true" :disabled="busy" @click="select(candidate.id, candidate.loginCustomerId)">Select</button><button v-if="candidate.manager !== false" :disabled="busy" @click="managerId = String(candidate.id); discover()">Explore manager</button></div><form class="row" @submit.prevent="select()"><label>Advertising account ID<input v-model="customerId" required placeholder="123-456-7890"></label><label>Login manager ID (if needed)<input v-model="loginId" placeholder="123-456-7890"></label><button :disabled="busy">Select account</button></form>
    <div v-for="account in google.accounts" :key="account.customer_id" class="account"><div class="heading"><h3>{{ account.name }} · {{ account.currency }}</h3><button :disabled="busy" @click="removeAccount(account.customer_id)">Remove</button></div><p>{{ account.customer_id }} · {{ account.time_zone }}</p><details><summary>Campaign attribution setup</summary><p>Add <code>xaylo_campaign_id={campaignid}</code> to your Google Ads final URL suffix so website sessions carry a stable campaign ID. Alternatively, map existing UTM campaign values below.</p><label>One UTM campaign=Google campaign ID pair per line<textarea v-model="mappingText[account.customer_id]" rows="3" placeholder="spring=123456789"></textarea></label><button :disabled="busy" @click="saveMappings(account.customer_id)">Save campaign mappings</button></details></div>
    </template></template></section>
    <section class="panel"><h2>Your marketing goals</h2><p>When connected, your business profile is read from GHL. These additional instructions describe what you want Xaylo’s analysis to achieve.</p><form @submit.prevent="saveContext"><div class="grid"><label>Services & offers<textarea v-model="strategy.services" maxlength="3000" rows="3"></textarea></label><label>Target audience<textarea v-model="strategy.audience" maxlength="3000" rows="3"></textarea></label><label>Goals<textarea v-model="strategy.goals" maxlength="3000" rows="3" placeholder="More qualified consultations within our existing budget"></textarea></label><label>Constraints<textarea v-model="strategy.constraints" maxlength="3000" rows="3" placeholder="Budget limits, service areas and brand requirements"></textarea></label></div><label>What counts as a website conversion?<textarea v-model="strategy.conversionDefinition" maxlength="1000" rows="2" placeholder="A confirmed consultation booking"></textarea></label><label>GHL custom field IDs for audience segmentation (optional, comma separated)<input v-model="segmentFields" placeholder="Use choice fields only; free-text values are excluded"></label><button :disabled="busy">Save goals</button></form></section>
    <section class="panel"><h2>Connect your AI assistant</h2><p>Add this MCP URL in your assistant’s connector settings: <code>{{ mcpUrl }}</code></p><p>When it opens Xaylo’s authorisation page, enter the connection code below. Approve only a request you started.</p><form class="row" @submit.prevent="inspect"><label>Connection code<input v-model="code" maxlength="12" pattern="[A-Fa-f0-9]{12}" required @input="pending = null"></label><button :disabled="busy">Review request</button></form><div v-if="pending" class="account"><h3>{{ pending.clientName }}</h3><p>Callback: {{ pending.redirectUri }}</p><p>Requested access: {{ pending.scope.includes('reports:generate') ? 'Read analysis and saved reports; generate and save AI reports.' : 'Read analysis and saved reports.' }}</p><p>This grants access only to this workspace.</p><button :disabled="busy" @click="approve">Approve connection</button></div><h3>Connected assistants</h3><p v-if="!grants.length">No active connections. New connections appear after the assistant completes authorisation.</p><div v-for="grant in grants" :key="grant.id" class="candidate"><span>{{ grant.name }} · expires {{ new Date(grant.expires_at).toLocaleDateString() }}</span><button :disabled="busy" @click="revoke(grant.id)">Revoke access</button></div></section>
    <p>GHL and Google Ads keep their source records. Xaylo stores connection credentials, its own journey events for 90 days, your goals, and saved reports until you delete them.</p>
  </div>
</template>
<style scoped>
.connections{max-width:1100px}h1{font-size:36px;margin:6px 0}.eyebrow{color:#e8b923;font-size:11px;letter-spacing:.15em}p{color:#b8bdd2;line-height:1.6}.panel{background:#171827;border:1px solid #303144;padding:25px;border-radius:14px;margin:20px 0}h2{font-size:21px;margin:0}h3{font-size:16px;margin-top:22px}.heading,.candidate{display:flex;justify-content:space-between;align-items:center;gap:15px}.heading h3{margin-top:0}.candidate{padding:12px 0;border-bottom:1px solid #303144;flex-wrap:wrap}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.row{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.row label{flex:1;min-width:180px}.row button{margin-bottom:12px}label{display:block;color:#b8bdd2;font-size:13px;margin:14px 0}input,textarea{display:block;width:100%;padding:12px;margin-top:7px;background:#10111d;color:#fff;border:1px solid #3a3d54;border-radius:8px;font:inherit}button{background:#e8b923;color:#111;border:0;padding:10px 14px;border-radius:8px;font-weight:700;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.account{border-top:1px solid #3a3d54;padding:18px 0;margin-top:15px}.error,.notice{padding:14px;border:1px solid #a65c56;border-radius:9px;color:#ffdfd7}.notice{color:#e8d17e;border-color:#7b692b}code,a{color:#e8d17e;overflow-wrap:anywhere}summary{cursor:pointer;color:#c8cce1}@media(max-width:650px){.grid{grid-template-columns:1fr}.heading{flex-wrap:wrap}}
</style>
